import { ASSETS_STORY_GRID, LOGO, LOGO_CAPTION, PALETTE, PROFILE_PICTURE, PROFILE_TEXTS, SWATCH_TEXTS } from '@/components/ds/ui/assets-story-scenes';
import { captionedBeat } from '@/components/ds/ui/story-caption';
