'use client';

import { resolveColor } from '@/components/ds/ui/ds-color';
import type { GlyphCell } from '@/components/ds/ui/dot-glyph-cells';
import type { DotGrid } from '@/components/ds/ui/dot-morph-dots';
import { DOT_STORY_MUTED_TEXT_COLOR, DOT_STORY_TEXT_COLOR, type DotStoryPlayer, type DotStoryStage, type DotStoryText } from '@/components/ds/ui/dot-story-player';
import { dotsPath } from '@/components/ds/ui/dot-svg-path';
import { cx as cn } from '@/components/ds/ui/cx';
import { useEffect, useRef, useState } from 'react';

export type LoadDotStory = (stage: DotStoryStage) => Promise<DotStoryPlayer>;

interface DotStoryProps {
	grid: DotGrid;
	/** The picture shown before the story plays, and instead of it with reduced motion. */
	resting: { cells: GlyphCell[]; texts?: DotStoryText[]; clearedPath?: string };
	/** Kept outside the component, so the story is only loaded once. */
	load: LoadDotStory;
	surfaceColor?: string;
	className?: string;
}

const percent = (share: number) => `${share * 100}%`;

/**
 * A looping picture in the brand dot grid. It plays only while on screen, and its code only downloads once it first
 * scrolls into view. The picture repaints the surface's colour around its dots (the grid's halo), and reaches that far
 * past its own box, so it can sit on a backdrop pattern.
 */
export function DotStory({ grid, resting, load, surfaceColor = 'var(--ds-color-bg-default)', className }: DotStoryProps) {
	const frameRef = useRef<HTMLDivElement>(null);
	const canvasRef = useRef<HTMLCanvasElement>(null);
	const [hasTakenOver, setHasTakenOver] = useState(false);

	const { columns, rows, pitch, dotRadius, ringStroke, haloRadius } = grid;
	const width = columns * pitch;
	const height = rows * pitch;
	const centresOf = (cells: GlyphCell[]) => cells.map((cell) => ({ cx: (cell.column + 0.5) * pitch, cy: (cell.row + 0.5) * pitch }));
	// A canvas keeps its own size when only its insets are set, so the box is spelled out in full.
	const surfaceBox = { left: percent(-haloRadius / width), top: percent(-haloRadius / height), width: percent(1 + (haloRadius * 2) / width), height: percent(1 + (haloRadius * 2) / height) };

	useEffect(() => {
		const frame = frameRef.current;
		const canvas = canvasRef.current;
		if (!frame || !canvas) return;
		if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

		let player: DotStoryPlayer | null = null;
		let isLoading = false;
		let isDisposed = false;
		let isOnScreen = false;

		const sync = () => player?.setRunning(isOnScreen && !document.hidden);

		// If the story fails to load, the resting picture simply stays.
		const start = async () => {
			isLoading = true;
			try {
				const style = getComputedStyle(canvas);
				const loaded = await load({ canvas, dotColor: style.color, surfaceColor: resolveColor(canvas, surfaceColor), fontFamily: style.fontFamily, onFirstFrame: () => setHasTakenOver(true) });
				if (isDisposed) {
					loaded.destroy();
					return;
				}
				player = loaded;
				sync();
			} catch {
				player = null;
			} finally {
				isLoading = false;
			}
		};

		const visibility = new IntersectionObserver(([entry]) => {
			isOnScreen = entry.isIntersecting;
			if (player) sync();
			else if (isOnScreen && !isLoading) void start();
		});
		visibility.observe(frame);
		document.addEventListener('visibilitychange', sync);
		const resizeObserver = new ResizeObserver(() => player?.resize());
		resizeObserver.observe(canvas);

		return () => {
			isDisposed = true;
			visibility.disconnect();
			document.removeEventListener('visibilitychange', sync);
			resizeObserver.disconnect();
			player?.destroy();
			setHasTakenOver(false);
		};
	}, [load, surfaceColor]);

	return (
		<div ref={frameRef} aria-hidden="true" className={cn('relative text-brand', className)} style={{ aspectRatio: `${width} / ${height}` }}>
			{/* Once the canvas has drawn, the static picture is dropped rather than hidden, so its dots leave the DOM. */}
			{!hasTakenOver && (
				<svg viewBox={`${-haloRadius} ${-haloRadius} ${width + haloRadius * 2} ${height + haloRadius * 2}`} className="absolute font-data" style={surfaceBox}>
					{haloRadius > 0 && <path style={{ fill: surfaceColor }} d={dotsPath(centresOf(resting.cells), haloRadius)} />}
					{resting.clearedPath && <path style={{ fill: surfaceColor }} d={resting.clearedPath} />}
					<path fill="none" stroke="currentColor" strokeWidth={ringStroke} d={dotsPath(centresOf(resting.cells.filter((cell) => !cell.filled)), dotRadius - ringStroke / 2)} />
					<g fill="currentColor">
						<path d={dotsPath(centresOf(resting.cells.filter((cell) => cell.filled)), dotRadius)} />
						{resting.texts?.map(({ text, x, y, size, weight, muted = false, anchor = 'start' }) => (
							<text key={`${x}:${y}`} x={x} y={y} fontSize={size} fontWeight={weight} style={{ fill: muted ? DOT_STORY_MUTED_TEXT_COLOR : DOT_STORY_TEXT_COLOR }} textAnchor={anchor} className="whitespace-pre">
								{text}
							</text>
						))}
					</g>
				</svg>
			)}
			<canvas ref={canvasRef} className={cn('absolute font-data', !hasTakenOver && 'invisible')} style={surfaceBox} />
		</div>
	);
}

import { ENRICH_RESTING, ENRICH_STORY_GRID, EYE_AT_REST, EYE_LOOK, ICONS, IDENTIFIER, LINK, PROFILES, paintEye } from '@/components/ds/ui/enrich-story-scenes';
import type { GlyphCell } from '@/components/ds/ui/dot-glyph-cells';
import { createGlyphShader, drawGlyphCells } from '@/components/ds/ui/dot-glyph-morph';
import { DOT_FILLED, DOT_HOLLOW } from '@/components/ds/ui/dot-morph-dots';
import { cellIndexIn, cellState, clamp01, hasRippleReached } from '@/components/ds/ui/dot-story-cells';
import { createDotStoryPlayer, dotStoryFont, paintDotStoryCursor, paintDotStoryText, type DotStoryPlayer, type DotStoryStage } from '@/components/ds/ui/dot-story-player';

/**
 * One sighting, played as a loop: an identifier is typed while the agent's eye reads along, the eye melts into the
 * company and the person behind it, a card draws itself round each and fills in line by line, and a link joins the
 * two. Then both profiles melt back into the eye.
 */

const TYPING = { startsAt: 0.4, charactersPerSecond: 11 };
const LOOKING = { startsAt: TYPING.startsAt, glances: 2, glanceSeconds: 1.4 };
const SPLIT = { startsAt: LOOKING.startsAt + LOOKING.glances * LOOKING.glanceSeconds + 0.3, seconds: 1.1 };
const FRAME = { startsAt: SPLIT.startsAt + SPLIT.seconds + 0.2, seconds: 0.5 };
const DETAIL = { firstAt: FRAME.startsAt + FRAME.seconds, everySeconds: 0.3, staggerSeconds: 0.15, seconds: 0.3 };
const LINK_UP = { startsAt: DETAIL.firstAt + PROFILES[0].details.length * DETAIL.everySeconds + 0.3, seconds: 0.4, pulseSeconds: 0.9 };
const RESET = { startsAt: LINK_UP.startsAt + 2.6, seconds: 1.1 };
const LOOP_SECONDS = RESET.startsAt + RESET.seconds + 0.3;
// Both profiles are filled in and linked, between two pulses: the picture the static art shows.
const RESTING_AT_SECONDS = LINK_UP.startsAt + LINK_UP.seconds + LINK_UP.pulseSeconds * 1.5;
const TEXT_FADE_SECONDS = 0.3;
const CURSOR_GAP = 3;

const { columns, rows, pitch } = ENRICH_STORY_GRID;
const cellIndex = cellIndexIn(ENRICH_STORY_GRID);
const WHOLE_GRID = { left: 0, top: 0, cellsPerSide: Math.max(columns, rows) };

const melt = (from: GlyphCell[], into: GlyphCell[]) => createGlyphShader({ grid: ENRICH_STORY_GRID, box: WHOLE_GRID, cells: from, drawTarget: (target) => drawGlyphCells(target, into, pitch) });
const detailStartsAt = (card: number, detail: number) => DETAIL.firstAt + card * DETAIL.staggerSeconds + detail * DETAIL.everySeconds;

// The glances are whole, so the eye is looking straight ahead again when it starts to melt.
function lookAt(seconds: number) {
	const looking = clamp01((seconds - LOOKING.startsAt) / (LOOKING.glances * LOOKING.glanceSeconds));
	return Math.round(EYE_LOOK * Math.sin(looking * LOOKING.glances * Math.PI * 2));
}

export function createEnrichStoryPlayer({ canvas, dotColor, surfaceColor, fontFamily, onFirstFrame }: DotStoryStage): DotStoryPlayer {
	const states = new Uint8Array(columns * rows);
	const split = melt(EYE_AT_REST.cells, ICONS.cells);
	const reset = melt(ENRICH_RESTING.cells, EYE_AT_REST.cells);

	// The canvas draws with whatever is loaded at the time, so the fonts are asked for before any text is typed.
	for (const text of [IDENTIFIER, ...ENRICH_RESTING.texts]) void document.fonts.load(dotStoryFont(text, fontFamily), text.text);

	const paintProfiles = (seconds: number) => {
		states.set(ICONS.states);
		const framed = (seconds - FRAME.startsAt) / FRAME.seconds;
		PROFILES.forEach((card, index) => {
			// The card draws itself outwards from its icon, in the corner it starts from.
			const farthest = Math.hypot(card.region.columns, card.region.rows);
			for (const cell of card.frame) {
				if (framed > 0 && hasRippleReached(Math.hypot(cell.column - card.region.left, cell.row - card.region.top) / farthest, framed)) states[cellIndex(cell)] = cellState(cell);
			}
			card.details.forEach((detail, step) => {
				const filledIn = (seconds - detailStartsAt(index, step)) / DETAIL.seconds;
				for (const cell of detail.cells) {
					if (filledIn > 0 && hasRippleReached((cell.column - card.region.left) / card.region.columns, filledIn)) states[cellIndex(cell)] = cellState(cell);
				}
			});
		});
	};

	const paintLink = (seconds: number) => {
		const since = seconds - LINK_UP.startsAt;
		if (since <= 0) return;
		LINK.forEach((cell, step) => {
			if (hasRippleReached(step / LINK.length, since / LINK_UP.seconds)) states[cellIndex(cell)] = DOT_HOLLOW;
		});
		if (since < LINK_UP.seconds) return;
		const head = Math.floor((((since - LINK_UP.seconds) % LINK_UP.pulseSeconds) / LINK_UP.pulseSeconds) * (LINK.length * 2));
		const travelling = LINK[head];
		if (travelling) states[cellIndex(travelling)] = DOT_FILLED;
	};

	const statesAt = (seconds: number) => {
		if (seconds >= RESET.startsAt) return reset({ morph: clamp01((seconds - RESET.startsAt) / RESET.seconds), spin: 0 });
		if (seconds >= SPLIT.startsAt + SPLIT.seconds) {
			paintProfiles(seconds);
			paintLink(seconds);
			return states;
		}
		if (seconds >= SPLIT.startsAt) return split({ morph: (seconds - SPLIT.startsAt) / SPLIT.seconds, spin: 0 });
		return paintEye(states, lookAt(seconds));
	};

	const paintIdentifier = (context: CanvasRenderingContext2D, seconds: number) => {
		const presence = 1 - clamp01((seconds - SPLIT.startsAt) / TEXT_FADE_SECONDS);
		if (presence <= 0) return;
		const typed = IDENTIFIER.text.slice(0, Math.max(0, Math.floor((seconds - TYPING.startsAt) * TYPING.charactersPerSecond)));
		// The line is centred on what it will read once typed, so it grows to the right rather than from its middle.
		context.font = dotStoryFont(IDENTIFIER, fontFamily);
		const left = IDENTIFIER.x - context.measureText(IDENTIFIER.text).width / 2;
		paintDotStoryText(context, fontFamily, { ...IDENTIFIER, text: typed, x: left, anchor: 'start' }, presence);
		if (typed.length === IDENTIFIER.text.length) return;
		paintDotStoryCursor(context, left + context.measureText(typed).width + CURSOR_GAP, IDENTIFIER, presence);
	};

	const paintDetails = (context: CanvasRenderingContext2D, seconds: number) => {
		const leaving = 1 - clamp01((seconds - RESET.startsAt) / TEXT_FADE_SECONDS);
		PROFILES.forEach((card, index) => {
			card.details.forEach((detail, step) => {
				const presence = clamp01((seconds - detailStartsAt(index, step)) / DETAIL.seconds) * leaving;
				for (const text of detail.texts) paintDotStoryText(context, fontFamily, text, presence);
			});
		});
	};

	return createDotStoryPlayer({
		canvas,
		dotColor,
		surfaceColor,
		onFirstFrame,
		grid: ENRICH_STORY_GRID,
		resting: { states: ENRICH_RESTING.states, atSeconds: RESTING_AT_SECONDS },
		frameAt(storySeconds) {
			const seconds = storySeconds % LOOP_SECONDS;
			return {
				states: statesAt(seconds),
				paintAbove(context) {
					paintIdentifier(context, seconds);
					paintDetails(context, seconds);
				},
			};
		},
	});
}

import { glyphCellsFromRows, type GlyphCell } from '@/components/ds/ui/dot-glyph-cells';
import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from '@/components/ds/ui/dot-morph-dots';
import { cellStates, cellsOfStates, outlineCells, placeCells, ringsWithSpeckle, solidWithSpeckle, type Region } from '@/components/ds/ui/dot-story-cells';
import type { DotStoryText } from '@/components/ds/ui/dot-story-player';

/**
 * The "Enrich any entity your agent sees" card's pictures, in the brand dot grid: the agent's eye reads an
 * identifier, and what it saw becomes the two things behind it, a company and a person, each with its profile.
 */

// The ring pattern behind the picture already keeps clear of it, so the dots need no halo of their own.
export const ENRICH_STORY_GRID: DotGrid = { columns: 58, rows: 38, pitch: 10, dotRadius: 3.2, ringStroke: 1, haloRadius: 0 };

const { columns: COLUMNS, rows: ROWS, pitch: PITCH } = ENRICH_STORY_GRID;
const x = (column: number) => column * PITCH;
const y = (row: number) => row * PITCH;
// Doto sits a third of its size below the middle of the row it is set on.
const baselineOn = (row: number, size: number) => y(row + 0.5) + size / 3;

export interface StoryPicture {
	states: Uint8Array;
	cells: GlyphCell[];
}

const pictureOf = (states: Uint8Array): StoryPicture => ({ states, cells: cellsOfStates(ENRICH_STORY_GRID, states) });

const EYE = { centre: { column: 28.5, row: 14.5 }, halfWidth: 16, halfHeight: 9, iris: 5.6, pupil: 2.2 };
/** How far the eye looks to either side, in columns. */
export const EYE_LOOK = 6;

const isInEye = (column: number, row: number) => {
	const across = (column - EYE.centre.column) / EYE.halfWidth;
	return Math.abs(across) <= 1 && Math.abs(row - EYE.centre.row) <= EYE.halfHeight * (1 - across * across);
};
const isOnEyelid = (column: number, row: number) => !isInEye(column - 1, row) || !isInEye(column + 1, row) || !isInEye(column, row - 1) || !isInEye(column, row + 1);

/** The eye, looking `look` columns off centre: a ringed white, a solid iris and the brand's hollow circle for a pupil. */
export function paintEye(states: Uint8Array, look: number) {
	for (let row = 0; row < ROWS; row++) {
		for (let column = 0; column < COLUMNS; column++) {
			const cell = row * COLUMNS + column;
			if (!isInEye(column, row)) states[cell] = DOT_ABSENT;
			else if (isOnEyelid(column, row)) states[cell] = DOT_FILLED;
			else {
				const fromIris = Math.hypot(column - EYE.centre.column - look, row - EYE.centre.row);
				states[cell] = fromIris <= EYE.pupil ? DOT_HOLLOW : fromIris <= EYE.iris ? solidWithSpeckle(column, row) : ringsWithSpeckle(column, row);
			}
		}
	}
	return states;
}

export const EYE_AT_REST = pictureOf(paintEye(new Uint8Array(COLUMNS * ROWS), 0));
// daily.dev and its co-founder are a customer story on this site, so the picture enriches an entity the page already names.
export const IDENTIFIER: DotStoryText = { text: '@idoshamun, daily.dev', x: x(COLUMNS / 2), y: baselineOn(30, 24), size: 24, weight: 700, anchor: 'middle' };

const CARD = { columns: 26, rows: 32, top: 3 };
const COMPANY_CARD: Region = { left: 0, top: CARD.top, columns: CARD.columns, rows: CARD.rows };
const PERSON_CARD: Region = { left: COLUMNS - CARD.columns, top: CARD.top, columns: CARD.columns, rows: CARD.rows };

// A tower with a lower wing beside it: a plain tower on a base line read as a top hat.
const BUILDING_ROWS = ['     ##### ', '     #o#o# ', '     ##### ', ' #####o#o# ', ' #o#o##### ', ' #####o#o# ', ' #o#o##### ', ' #####o#o# ', ' #o#o##### ', ' ######o## ', ' ######o## '];
const PERSON_ROWS = ['    ###    ', '   #ooo#   ', '   #ooo#   ', '   #ooo#   ', '    ###    ', '           ', '  #######  ', ' ######### ', '###########', '###########', '###########'];
const ICON_INSET = 2;
const FACT_ROWS = [18, 22, 26];
const FOOT_ROW = 29;

export interface ProfileDetail {
	cells: GlyphCell[];
	texts: DotStoryText[];
}

export interface Profile {
	region: Region;
	icon: GlyphCell[];
	frame: GlyphCell[];
	/** The profile's lines, in the order they are filled in. */
	details: ProfileDetail[];
}

interface ProfileSpec {
	region: Region;
	iconRows: string[];
	name: string;
	handle: string;
	facts: string[];
	foot: ProfileDetail;
}

function profile({ region, iconRows, name, handle, facts, foot }: ProfileSpec): Profile {
	const textLeft = x(region.left + ICON_INSET + 12);
	const heading: ProfileDetail = {
		cells: [],
		texts: [
			{ text: name, x: textLeft, y: baselineOn(region.top + 6, 18), size: 18, weight: 800 },
			{ text: handle, x: textLeft, y: baselineOn(region.top + 9, 12), size: 12, weight: 700, muted: true },
		],
	};
	const lines = facts.map((fact, index): ProfileDetail => {
		const row = region.top + FACT_ROWS[index];
		return { cells: [{ column: region.left + 3, row, filled: true }], texts: [{ text: fact, x: x(region.left + 5), y: baselineOn(row, 14), size: 14, weight: 600 }] };
	});
	return { region, icon: placeCells(glyphCellsFromRows(iconRows), { left: region.left + ICON_INSET, top: region.top + ICON_INSET }), frame: outlineCells(region), details: [heading, ...lines, foot] };
}

// Three brand colours, as three densities of the brand's two circles.
const SWATCH = { columns: 3, rows: 2, gap: 1 };
const swatches: GlyphCell[] = [0, 1, 2].flatMap((shade) =>
	Array.from({ length: SWATCH.columns * SWATCH.rows }, (_, index) => {
		const column = index % SWATCH.columns;
		const row = Math.floor(index / SWATCH.columns);
		return { column: COMPANY_CARD.left + 3 + shade * (SWATCH.columns + SWATCH.gap) + column, row: COMPANY_CARD.top + FOOT_ROW + row, filled: [true, (column + row) % 2 === 0, false][shade] };
	})
);

export const PROFILES: Profile[] = [
	profile({ region: COMPANY_CARD, iconRows: BUILDING_ROWS, name: 'daily.dev', handle: 'Company', facts: ['Developer network', 'Programming news', 'Millions of devs'], foot: { cells: swatches, texts: [] } }),
	profile({
		region: PERSON_CARD,
		iconRows: PERSON_ROWS,
		name: 'Ido Shamun',
		handle: '@idoshamun',
		facts: ['Co-founder', 'at daily.dev'],
		foot: { cells: [], texts: [{ text: 'x.com/idoshamun', x: x(PERSON_CARD.left + 3), y: baselineOn(PERSON_CARD.top + FOOT_ROW + 0.5, 13), size: 13, weight: 700, muted: true }] },
	}),
];

/** The company and the person on their own: dense enough for the eye to melt into. */
export const ICONS = pictureOf(
	cellStates(
		ENRICH_STORY_GRID,
		PROFILES.flatMap((card) => card.icon)
	)
);

const LINK_ROW = CARD.top + Math.floor(CARD.rows / 2);
/** The rule that joins the person to the company, in the order a pulse travels it. */
export const LINK: GlyphCell[] = Array.from({ length: PERSON_CARD.left - CARD.columns }, (_, step) => ({ column: PERSON_CARD.left - 1 - step, row: LINK_ROW, filled: false }));

/** Both profiles, linked: what the picture shows before it plays, and instead of playing with reduced motion. */
export const ENRICH_RESTING = {
	...pictureOf(cellStates(ENRICH_STORY_GRID, [...PROFILES.flatMap((card) => [...card.frame, ...card.icon, ...card.details.flatMap((detail) => detail.cells)]), ...LINK])),
	texts: PROFILES.flatMap((card) => card.details.flatMap((detail) => detail.texts)),
};

'use client';

import { ENRICH_RESTING, ENRICH_STORY_GRID } from '@/components/ds/ui/enrich-story-scenes';
import { DotStory, type LoadDotStory } from '@/components/ds/ui/dot-story';

const loadEnrichStory: LoadDotStory = async (stage) => {
	const { createEnrichStoryPlayer } = await import('@/components/ds/ui/enrich-story-player');
	return createEnrichStoryPlayer(stage);
};

/**
 * The "Enrich any entity your agent sees" card's picture: the agent's eye reads an identifier and melts into the
 * company and the person behind it, each with its profile. With reduced motion it shows both profiles, linked.
 */
export function EnrichStory({ className }: { className?: string }) {
	return <DotStory grid={ENRICH_STORY_GRID} resting={ENRICH_RESTING} load={loadEnrichStory} className={className} />;
}

import { BLANK_WINDOW, EXTRACT_STORY_GRID, FORMATS, OUTPUT_TEXT, OUTPUT_WINDOWS, PAGE, PAGE_LABELS, PUBLISHED_PAGE, tabsFor, WINDOW_ROWS, WINDOW_TOP_ROW, type Format } from '@/components/ds/ui/extract-story-scenes';
import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW } from '@/components/ds/ui/dot-morph-dots';
import { createBeatStoryPlayer, typingSeconds, type StoryBeat } from '@/components/ds/ui/dot-story-beats';
import { clamp01 } from '@/components/ds/ui/dot-story-cells';
import type { DotStoryPlayer, DotStoryStage } from '@/components/ds/ui/dot-story-player';

/**
 * One scrape, played as a loop: a scan runs down a live webpage, reading its rings into solid dots; the page melts
 * into a window; then the window steps through each output format in turn, typing the text ones and building the
 * image and screenshot ones.
 */

const SCAN = { startsAt: 0.5, seconds: 2.2 };
const MELT_SECONDS = 1.1;
const WIPE_SECONDS = 0.5;
const TAB_SWITCH_SECONDS = 0.35;
const TYPING = { startsAt: 0.25, charactersPerSecond: 44, pauseSeconds: 0.1 };
const PICTURE_HOLD_SECONDS = 2.2;

const { columns } = EXTRACT_STORY_GRID;

// Everything above the scan has been read; the scan itself is a solid bar across the page.
function scanPage(states: Uint8Array, heldSeconds: number) {
	const scanned = clamp01((heldSeconds - SCAN.startsAt) / SCAN.seconds);
	if (scanned <= 0) return;
	const bar = PAGE.top + Math.round(scanned * (PAGE.bottom - PAGE.top));
	for (let row = PAGE.top + 4; row <= Math.min(bar, PAGE.bottom - 1); row++) {
		for (let column = PAGE.left + 1; column < PAGE.right; column++) {
			const cell = row * columns + column;
			if (states[cell] === DOT_HOLLOW || (row === bar && scanned < 1 && PUBLISHED_PAGE.states[cell] === DOT_ABSENT)) states[cell] = DOT_FILLED;
		}
	}
}

const topToBottom = (_column: number, row: number) => clamp01((row - WINDOW_TOP_ROW) / WINDOW_ROWS);

function formatBeat(format: Format, isFirst: boolean): StoryBeat {
	const texts = OUTPUT_TEXT[format];
	const typed = format === 'Markdown' || format === 'HTML' || format === 'JSON' || format === 'Highlights';
	const startsAt = texts.map((_, index) => TYPING.startsAt + texts.slice(0, index).reduce((total, text) => total + typingSeconds(text, TYPING.charactersPerSecond) + TYPING.pauseSeconds, 0));
	const typingEnds = texts.length === 0 ? 0 : startsAt[texts.length - 1] + typingSeconds(texts[texts.length - 1], TYPING.charactersPerSecond);
	return {
		picture: OUTPUT_WINDOWS[format],
		arrival: { kind: 'builds', seconds: isFirst ? WIPE_SECONDS : TAB_SWITCH_SECONDS, order: topToBottom },
		holdSeconds: typed ? typingEnds + 0.9 : PICTURE_HOLD_SECONDS,
		write(pen, heldSeconds) {
			tabsFor(format).forEach((tab) => pen.text(tab));
			if (typed) texts.forEach((text, index) => pen.type(text, heldSeconds, { startsAt: startsAt[index], charactersPerSecond: TYPING.charactersPerSecond }));
			else texts.forEach((text) => pen.text(text));
		},
	};
}

export function createExtractStoryPlayer(stage: DotStoryStage): DotStoryPlayer {
	return createBeatStoryPlayer(stage, {
		grid: EXTRACT_STORY_GRID,
		// It starts on the live page, so a visitor first sees what is being scraped, then each output in turn.
		resting: { beat: 0, heldSeconds: 0 },
		beats: [
			{ picture: PUBLISHED_PAGE, arrival: { kind: 'melts', seconds: MELT_SECONDS }, holdSeconds: SCAN.startsAt + SCAN.seconds + 0.5, animate: scanPage, write: (pen) => PAGE_LABELS.forEach((label) => pen.text(label)) },
			{ picture: BLANK_WINDOW, arrival: { kind: 'melts', seconds: MELT_SECONDS }, holdSeconds: 0.2 },
			...FORMATS.map((format, index) => formatBeat(format, index === 0)),
			{ picture: BLANK_WINDOW, arrival: { kind: 'builds', seconds: WIPE_SECONDS, order: topToBottom }, holdSeconds: 0.1 },
		],
	});
}

import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from '@/components/ds/ui/dot-morph-dots';
import { pictureOf } from '@/components/ds/ui/dot-story-beats';
import { rectangle, rings, solidWithSpeckle, stack, within, type DotPainter } from '@/components/ds/ui/dot-story-cells';
import type { DotStoryText } from '@/components/ds/ui/dot-story-player';

/**
 * The Scrape card's pictures, in the brand dot grid: a live webpage in a browser, and the window it is scraped into,
 * one output format per tab (Markdown, HTML, JSON, images, a screenshot and highlights).
 */

// The ring pattern behind the picture already keeps clear of it, so the dots need no halo of their own.
export const EXTRACT_STORY_GRID: DotGrid = { columns: 58, rows: 38, pitch: 10, dotRadius: 3.2, ringStroke: 1, haloRadius: 0 };

const PITCH = EXTRACT_STORY_GRID.pitch;
const x = (column: number) => column * PITCH;
// Doto sits a third of its size below the middle of the row it is set on.
const baselineOn = (row: number, size: number) => (row + 0.5) * PITCH + size / 3;

interface Box {
	left: number;
	right: number;
	top: number;
	bottom: number;
}

const inBox = (box: Box, column: number, row: number) => column >= box.left && column <= box.right && row >= box.top && row <= box.bottom;

/**
 * A marketing page's layout inside `box`, scaled to it: nav, a hero with a heading, copy and two buttons beside a
 * picture, and a row of three cards. Used for the live page and, smaller, for its screenshot.
 */
function webpageLayout(box: Box): DotPainter {
	const width = box.right - box.left;
	const height = box.bottom - box.top;
	const at = (share: number) => box.left + Math.round(share * width);
	const down = (share: number) => box.top + Math.round(share * height);
	const nav = { row: down(0.08), logoTo: at(0.1), links: [at(0.62), at(0.74), at(0.86)], linkWidth: Math.max(1, Math.round(width * 0.07)) };
	const heading = { top: down(0.2), bottom: down(0.2) + Math.max(1, Math.round(height * 0.05)), to: at(0.52) };
	const copy = [
		{ row: down(0.36), to: at(0.56) },
		{ row: down(0.44), to: at(0.46) },
	];
	const buttons = { top: down(0.54), bottom: down(0.54) + Math.max(1, Math.round(height * 0.04)), primaryTo: at(0.18), secondaryFrom: at(0.22), secondaryTo: at(0.38) };
	const picture = { left: at(0.64), right: at(0.96), top: down(0.2), bottom: down(0.6) };
	const cardsTop = down(0.7);
	const cards = [0, 1, 2].map((index) => ({ left: at(0.04 + index * 0.32), right: at(0.3 + index * 0.32) }));
	return (column, row) => {
		if (row === nav.row) return column <= nav.logoTo || nav.links.some((from) => column >= from && column < from + nav.linkWidth) ? (column <= nav.logoTo ? DOT_FILLED : DOT_HOLLOW) : DOT_ABSENT;
		if (row >= heading.top && row <= heading.bottom && column <= heading.to) return DOT_FILLED;
		const line = copy.find((candidate) => candidate.row === row);
		if (line && column <= line.to) return DOT_HOLLOW;
		if (row >= buttons.top && row <= buttons.bottom) {
			if (column <= buttons.primaryTo) return DOT_FILLED;
			if (column >= buttons.secondaryFrom && column <= buttons.secondaryTo) return row === buttons.top || row === buttons.bottom || column === buttons.secondaryFrom || column === buttons.secondaryTo ? DOT_FILLED : DOT_ABSENT;
		}
		if (inBox(picture, column, row)) return solidWithSpeckle(column, row);
		const card = cards.find((candidate) => column >= candidate.left && column <= candidate.right);
		if (card && row >= cardsTop && row < box.bottom) {
			const cardHeight = box.bottom - cardsTop;
			if (row < cardsTop + Math.round(cardHeight * 0.55)) return solidWithSpeckle(column, row);
			return (row - cardsTop) % 2 === 0 && column < card.right - 1 ? DOT_HOLLOW : DOT_ABSENT;
		}
		return DOT_ABSENT;
	};
}

export const PAGE = { left: 4, right: 53, top: 1, bottom: 36 };
const ADDRESS_BAR = { top: PAGE.top, bottom: PAGE.top + 3, from: PAGE.left + 10, to: PAGE.right - 2 };
const BROWSER_BUTTONS = { row: PAGE.top + 2, columns: [PAGE.left + 2, PAGE.left + 4, PAGE.left + 6] };
const PAGE_BODY: Box = { left: PAGE.left + 3, right: PAGE.right - 3, top: ADDRESS_BAR.bottom + 2, bottom: PAGE.bottom - 2 };

const browser = rectangle(PAGE, (column, row) => {
	if (row <= ADDRESS_BAR.bottom) {
		if (row === BROWSER_BUTTONS.row && BROWSER_BUTTONS.columns.includes(column)) return DOT_HOLLOW;
		// The address field is left empty, and the page's URL is written in it.
		if (row > ADDRESS_BAR.top && row < ADDRESS_BAR.bottom && column >= ADDRESS_BAR.from && column <= ADDRESS_BAR.to) return DOT_ABSENT;
		return DOT_FILLED;
	}
	return inBox(PAGE_BODY, column, row) ? webpageLayout(PAGE_BODY)(column, row) : DOT_ABSENT;
});

export const PUBLISHED_PAGE = pictureOf(EXTRACT_STORY_GRID, browser);
export const PAGE_LABELS: DotStoryText[] = [{ text: 'https://atlas.example/pricing', x: x(ADDRESS_BAR.from + 1), y: baselineOn(ADDRESS_BAR.top + 1.5, 13), size: 13, weight: 700, muted: true }];

const WINDOW = { left: 3, right: 54, top: 2, bottom: 35 };
const TITLE_BAR_BOTTOM = WINDOW.top + 3;
const BUTTONS = { row: WINDOW.top + 2, columns: [6, 8, 10] };
const TAB_RULE_ROW = TITLE_BAR_BOTTOM + 5;
export const WINDOW_TOP_ROW = TITLE_BAR_BOTTOM;
export const WINDOW_ROWS = WINDOW.bottom - TITLE_BAR_BOTTOM;

const TAB_SIZE = 13;
// Doto is monospaced, each letter three fifths of its size wide.
const tabWidthInColumns = (text: string) => (text.length * 0.6 * TAB_SIZE) / PITCH;
export const FORMATS = ['Markdown', 'HTML', 'JSON', 'Images', 'Screenshot', 'Highlights'] as const;
export type Format = (typeof FORMATS)[number];
const TAB_GAP_COLUMNS = 2;
const TAB_POSITIONS = FORMATS.reduce<{ format: Format; from: number; to: number }[]>((positions, format) => {
	const from = positions.length === 0 ? WINDOW.left + 3 : positions[positions.length - 1].to + TAB_GAP_COLUMNS;
	return [...positions, { format, from, to: from + tabWidthInColumns(format) }];
}, []);

const tabRule = (active: Format): DotPainter => {
	const tab = TAB_POSITIONS.find((position) => position.format === active)!;
	return (column, row) => {
		if (row !== TAB_RULE_ROW || column < WINDOW.left + 2 || column > WINDOW.right - 2) return DOT_ABSENT;
		return column >= Math.floor(tab.from) && column <= Math.ceil(tab.to) - 1 ? DOT_FILLED : DOT_HOLLOW;
	};
};

// A window that is only an outline has too little in it to melt into or out of, so it arrives and leaves full of
// rings and wipes clear in between.
function outputWindow(body: DotPainter): DotPainter {
	return rectangle(WINDOW, (column, row) => {
		if (row <= TITLE_BAR_BOTTOM) return row === BUTTONS.row && BUTTONS.columns.includes(column) ? DOT_HOLLOW : DOT_FILLED;
		return body(column, row);
	});
}

const CONTENT: Box = { left: WINDOW.left + 3, right: WINDOW.right - 3, top: TAB_RULE_ROW + 3, bottom: WINDOW.bottom - 3 };

// Three image thumbnails pulled off the page, each with its file name written under it.
const THUMBNAILS = [0, 1, 2].map((index) => {
	const width = (CONTENT.right - CONTENT.left - 4) / 3;
	const left = Math.round(CONTENT.left + index * (width + 2));
	return { left, right: Math.round(left + width - 1), top: CONTENT.top, bottom: CONTENT.top + 11 };
});
const thumbnails: DotPainter = (column, row) => {
	const thumbnail = THUMBNAILS.find((box) => inBox(box, column, row));
	if (!thumbnail) return DOT_ABSENT;
	return column === thumbnail.left || column === thumbnail.right || row === thumbnail.top || row === thumbnail.bottom ? DOT_FILLED : solidWithSpeckle(column, row);
};

// The page as captured: the same layout, framed and smaller.
const SCREENSHOT: Box = { left: CONTENT.left + 4, right: CONTENT.right - 4, top: CONTENT.top, bottom: CONTENT.bottom + 1 };
const SCREENSHOT_BODY: Box = { left: SCREENSHOT.left + 2, right: SCREENSHOT.right - 2, top: SCREENSHOT.top + 2, bottom: SCREENSHOT.bottom - 1 };
const screenshot = stack(
	within(
		(column, row) => inBox(SCREENSHOT, column, row) && (column === SCREENSHOT.left || column === SCREENSHOT.right || row === SCREENSHOT.top || row === SCREENSHOT.bottom),
		() => DOT_FILLED
	),
	within((column, row) => inBox(SCREENSHOT_BODY, column, row), webpageLayout(SCREENSHOT_BODY))
);

const BODIES: Record<Format, DotPainter> = {
	Markdown: () => DOT_ABSENT,
	HTML: () => DOT_ABSENT,
	JSON: () => DOT_ABSENT,
	Images: thumbnails,
	Screenshot: screenshot,
	Highlights: () => DOT_ABSENT,
};

export const BLANK_WINDOW = pictureOf(EXTRACT_STORY_GRID, outputWindow(rings));
export const OUTPUT_WINDOWS = Object.fromEntries(FORMATS.map((format) => [format, pictureOf(EXTRACT_STORY_GRID, outputWindow(stack(tabRule(format), BODIES[format])))])) as Record<Format, ReturnType<typeof pictureOf>>;

export const tabsFor = (active: Format): DotStoryText[] => TAB_POSITIONS.map((tab) => ({ text: tab.format, x: x(tab.from), y: baselineOn(TAB_RULE_ROW - 2.5, TAB_SIZE), size: TAB_SIZE, weight: tab.format === active ? 800 : 700, muted: tab.format !== active }));

const TEXT_LEFT = x(CONTENT.left);
const line = (text: string, rowOffset: number, isStrong: boolean, size = 16): DotStoryText => ({ text, x: TEXT_LEFT, y: baselineOn(CONTENT.top + rowOffset, size), size, weight: isStrong ? 800 : 600 });

export const OUTPUT_TEXT: Record<Format, DotStoryText[]> = {
	Markdown: [line('# Atlas pricing', 0, true), line('## Starter', 4, true), line('- $19 / month', 7, false), line('- 10,000 requests / month', 10, false), line('## Team', 14, true), line('- $49 / month', 17, false)],
	HTML: [line('<h1>Atlas pricing</h1>', 0, true, 15), line('<h2>Starter</h2>', 4, false, 15), line('<p>$19 / month</p>', 7, false, 15), line('<h2>Team</h2>', 11, false, 15), line('<p>$49 / month</p>', 14, false, 15)],
	JSON: [line('{', 0, false, 15), line('  "title": "Atlas pricing",', 3, false, 15), line('  "plans": ["Starter", "Team"],', 6, false, 15), line('  "prices": [19, 49]', 9, false, 15), line('}', 12, false, 15)],
	Images: THUMBNAILS.map((box, index) => ({ text: ['hero.webp', 'logo.svg', 'team.jpg'][index], x: x(box.left), y: baselineOn(box.bottom + 2.5, 12), size: 12, weight: 700, muted: true })),
	Screenshot: [],
