/**
 * The invitation, played as a loop: a banner sweeps in and asks its question, then melts into a paper plane, which
 * draws back and flies off to the top right.
 */

const TYPING = { startsAt: 0.3, charactersPerSecond: 12 };
const ASKED_AT = TYPING.startsAt + typingSeconds(QUESTION, TYPING.charactersPerSecond);
const MELT_SECONDS = 1.1;
const FLIGHT = { startsAt: 0.45, seconds: 1.6, drawBack: 1.4 };
// The plane has already left when the loop comes round, so the banner arrives on an empty grid rather than on the
// plane's resting picture.
const CLEARED_SECONDS = 0.5;

// Eases in from a step backwards, so the plane draws back before it goes.
const launch = (t: number) => t * t * ((FLIGHT.drawBack + 1) * t - FLIGHT.drawBack);

export function createFaqDemoStoryPlayer(stage: DotStoryStage): DotStoryPlayer {
	const bannerInside = new Path2D(BANNER_INSIDE);
	return createBeatStoryPlayer(stage, {
		grid: FAQ_DEMO_STORY_GRID,
		resting: { beat: 2, heldSeconds: ASKED_AT },
		beats: [
			{ picture: EMPTY, arrival: { kind: 'builds', seconds: 0, order: () => 0 }, holdSeconds: CLEARED_SECONDS },
			{ picture: BANNER_FILLED, arrival: { kind: 'waves', seconds: 0.9, origin: BANNER_ORIGIN }, holdSeconds: 0.15 },
			{
				picture: BANNER_OPEN,
				arrival: { kind: 'builds', seconds: 0.5, order: bannerShare },
				holdSeconds: ASKED_AT + 1.5,
				write: (pen, heldSeconds) => pen.type(QUESTION, heldSeconds, { ...TYPING, cursorLingers: Infinity }),
				clears: (context) => context.fill(bannerInside),
			},
			{ picture: BANNER_FILLED, arrival: { kind: 'builds', seconds: 0.4, order: bannerShare }, holdSeconds: 0.1 },
			{
				picture: PLANE_AT_REST,
				arrival: { kind: 'melts', seconds: MELT_SECONDS },
				holdSeconds: FLIGHT.startsAt + FLIGHT.seconds,
				animate(states, heldSeconds) {
					if (heldSeconds < FLIGHT.startsAt) return;
					paintFlight(states, FLIGHT_COLUMNS * launch(clamp01((heldSeconds - FLIGHT.startsAt) / FLIGHT.seconds)));
				},
			},
		],
	});
}

import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from '@/components/ds/ui/dot-morph-dots';
import { pictureOf, type StoryPicture } from '@/components/ds/ui/dot-story-beats';
import { clear, polygon, ringsWithSpeckle, solidWithSpeckle, stack, type DotPainter, type GridPoint } from '@/components/ds/ui/dot-story-cells';
import type { DotStoryText } from '@/components/ds/ui/dot-story-player';

/**
 * The FAQ invite's pictures, in the brand dot grid: a banner asking for questions and the paper plane it becomes,
 * which flies off from the bottom left to the top right.
 */

// The picture covers the whole of its ring pattern, so the plane can leave by the pattern's own corner; the halo is
// what clears the pattern from around its dots.
export const FAQ_DEMO_STORY_GRID: DotGrid = { columns: 56, rows: 42, pitch: 10, dotRadius: 3.2, ringStroke: 1, haloRadius: 14 };

const { columns: COLUMNS, rows: ROWS, pitch: PITCH } = FAQ_DEMO_STORY_GRID;
// Doto sits a third of its size below the middle of the row it is set on.
const baselineOn = (row: number, size: number) => (row + 0.5) * PITCH + size / 3;
const middleOf = (from: number, to: number) => ((from + to) / 2 + 0.5) * PITCH;
const centreOf = (index: number) => (index + 0.5) * PITCH;

// Its bottom edge sits on the grid's last row, level with the foot of the FAQ list beside it.
const BANNER = { left: 3, right: 46, top: 29, bottom: 41, tail: 5 };
const BANNER_MIDDLE = (BANNER.top + BANNER.bottom) / 2;
export const BANNER_ORIGIN: GridPoint = { column: BANNER.left, row: BANNER_MIDDLE };

// A ribbon with a swallowtail cut into each end: a plain box read as another button.
const BANNER_CORNERS: GridPoint[] = [
	{ column: BANNER.left, row: BANNER.top },
	{ column: BANNER.right, row: BANNER.top },
	{ column: BANNER.right - BANNER.tail, row: BANNER_MIDDLE },
	{ column: BANNER.right, row: BANNER.bottom },
	{ column: BANNER.left, row: BANNER.bottom },
	{ column: BANNER.left + BANNER.tail, row: BANNER_MIDDLE },
];
const banner = (interior: DotPainter) => polygon(BANNER_CORNERS, interior);
/** The banner's inside as a path in grid units, for clearing the ring pattern from behind its question. */
export const BANNER_INSIDE = `M${BANNER_CORNERS.map(({ column, row }) => `${centreOf(column)} ${centreOf(row)}`).join('L')}Z`;

export const BANNER_FILLED = pictureOf(FAQ_DEMO_STORY_GRID, banner(ringsWithSpeckle));
export const BANNER_OPEN = pictureOf(FAQ_DEMO_STORY_GRID, banner(clear));
export const bannerShare = (column: number) => (column - BANNER.left) / (BANNER.right - BANNER.left);

// Doto is monospaced, each letter three fifths of its size wide.
const DOTO_ADVANCE = 0.6;
const QUESTION_TEXT = 'Ask anything';
const QUESTION_SIZE = 30;
// Set from its left edge, not its middle: it is typed, and the cursor stands at the end of what has been typed so far.
export const QUESTION: DotStoryText = { text: QUESTION_TEXT, x: middleOf(BANNER.left, BANNER.right) - ((QUESTION_TEXT.length + 1) * DOTO_ADVANCE * QUESTION_SIZE) / 2, y: baselineOn(BANNER_MIDDLE, QUESTION_SIZE), size: QUESTION_SIZE, weight: 800 };

const PLANE = { left: 8, top: 17 };
const planePoint = (column: number, row: number): GridPoint => ({ column: PLANE.left + column, row: PLANE.top + row });
const NOSE = planePoint(24, 0);
const WING_TIP = planePoint(0, 9);
const FOLD = planePoint(9, 13);
const KEEL = planePoint(13, 20);

// The wing seen from above is solid and the keel beneath it rings, which is what makes the fold read as a fold.
const plane = stack(polygon([WING_TIP, NOSE, FOLD], solidWithSpeckle), polygon([FOLD, NOSE, KEEL], ringsWithSpeckle));
export const PLANE_AT_REST: StoryPicture = pictureOf(FAQ_DEMO_STORY_GRID, plane);

export const EMPTY = pictureOf(FAQ_DEMO_STORY_GRID, clear);

// The way out is shallower than the plane's own heading, so it leaves by the top right corner and not through the top.
const CLIMB = 0.72;
const TRAIL = { every: 3, columns: 21, gap: 2 };
/** Far enough that the plane and the trail behind it have both left the grid. */
export const FLIGHT_COLUMNS = COLUMNS - PLANE.left + TRAIL.columns;

const isOnGrid = (column: number, row: number) => column >= 0 && column < COLUMNS && row >= 0 && row < ROWS;

/** The plane `travelled` columns along its way out, with the trail it leaves behind its fold. */
export function paintFlight(states: Uint8Array, travelled: number) {
	// Whole cells, so the plane keeps its shape as it moves instead of being redrawn a little differently each frame.
	const across = Math.round(travelled);
	const up = Math.round(travelled * CLIMB);
	states.fill(DOT_ABSENT);

	for (let step = Math.max(0, across - TRAIL.columns); step <= across - TRAIL.gap; step++) {
		if (step % TRAIL.every !== 0) continue;
		const column = FOLD.column - 1 + step;
		const row = FOLD.row + 1 - Math.round(step * CLIMB);
		if (isOnGrid(column, row)) states[row * COLUMNS + column] = DOT_HOLLOW;
	}
	for (const cell of PLANE_AT_REST.cells) {
		const column = cell.column + across;
		const row = cell.row - up;
		if (isOnGrid(column, row)) states[row * COLUMNS + column] = cell.filled ? DOT_FILLED : DOT_HOLLOW;
	}
	return states;
}

/** The banner with its question: what the picture shows before it plays, and instead of playing with reduced motion. */
export const FAQ_DEMO_RESTING = { ...BANNER_OPEN, texts: [QUESTION], clearedPath: BANNER_INSIDE };

import { CACHED_AGE, CACHE_AT_REST, CAPTIONS, DIAL_CACHED, DIAL_FRESH, DIAL_LABELS, FRESHNESS_STORY_GRID, GLOBE_AT_REST, GLOBE_TURN, ONE_HOUR_MS, paintCache, paintDial, paintGlobe } from '@/components/ds/ui/freshness-story-scenes';
import { createBeatStoryPlayer, type StoryBeat, type StoryPicture } from '@/components/ds/ui/dot-story-beats';
import { clamp01 } from '@/components/ds/ui/dot-story-cells';
import type { DotStoryPlayer, DotStoryStage, DotStoryText } from '@/components/ds/ui/dot-story-player';

/**
 * Two requests for the same page, played as a loop: the dial is turned up to accept an hour-old copy, and melts
 * into the cache that copy is read from; then it is turned back to zero, and melts into the live web the fresh
 * capture goes out to.
 */

const MELT_SECONDS = 1.1;
const TURN = { startsAt: 0.35, seconds: 1.2 };
const READ = { startsAt: 0.4, seconds: 0.9 };
const DETAIL = { fadeSeconds: 0.3 };
// The globe looks the same after each second of turning, so the picture the story rests on is one it really shows.
const GLOBE_TURNS_PER_SECOND = 1;
const MS_STEP = 1000;

const easeInOut = (t: number) => (t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2);

function captioned(picture: StoryPicture, holdSeconds: number, animate: NonNullable<StoryBeat['animate']>, [label, value, detail]: DotStoryText[], detailAt: number): StoryBeat {
	return {
		picture,
		arrival: { kind: 'melts', seconds: MELT_SECONDS },
		holdSeconds,
		animate,
		write(pen, heldSeconds) {
			pen.text(label);
			pen.text(value);
			pen.text(detail, clamp01((heldSeconds - detailAt) / DETAIL.fadeSeconds));
		},
	};
}

/** The dial turned from one age to another, its reading counting along with the needle. */
function dialBeat(picture: StoryPicture, departure: StoryPicture, from: number, to: number, caption: DotStoryText[]): StoryBeat {
	const ageAt = (heldSeconds: number) => from + (to - from) * easeInOut(clamp01((heldSeconds - TURN.startsAt) / TURN.seconds));
	const beat = captioned(picture, TURN.startsAt + TURN.seconds + 1.1, (states, heldSeconds) => void paintDial(states, ageAt(heldSeconds)), caption, TURN.startsAt + TURN.seconds);
	return {
		...beat,
		departure,
		write(pen, heldSeconds) {
			const [label, value, detail] = caption;
			const reading = Math.round(((ageAt(heldSeconds) / CACHED_AGE) * ONE_HOUR_MS) / MS_STEP) * MS_STEP;
			pen.text(label);
			pen.text({ ...value, text: String(reading) });
			pen.text(detail, clamp01((heldSeconds - TURN.startsAt - TURN.seconds) / DETAIL.fadeSeconds));
			DIAL_LABELS.forEach((dialLabel) => pen.text(dialLabel));
		},
	};
}

export function createFreshnessStoryPlayer(stage: DotStoryStage): DotStoryPlayer {
	return createBeatStoryPlayer(stage, {
		grid: FRESHNESS_STORY_GRID,
		resting: { beat: 3, heldSeconds: 2 },
		beats: [
			dialBeat(DIAL_FRESH, DIAL_CACHED, 0, CACHED_AGE, CAPTIONS.acceptCached),
			captioned(CACHE_AT_REST, 2.6, (states, heldSeconds) => void paintCache(states, clamp01((heldSeconds - READ.startsAt) / READ.seconds)), CAPTIONS.cached, READ.startsAt + READ.seconds),
			dialBeat(DIAL_CACHED, DIAL_FRESH, CACHED_AGE, 0, CAPTIONS.requireFresh),
			captioned(GLOBE_AT_REST, 3, (states, heldSeconds) => void paintGlobe(states, heldSeconds * GLOBE_TURNS_PER_SECOND * GLOBE_TURN), CAPTIONS.fresh, 0.5),
		],
	});
}

import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from '@/components/ds/ui/dot-morph-dots';
import type { StoryPicture } from '@/components/ds/ui/dot-story-beats';
import { cellsOfStates, distanceToSegment, isFilledAmongSolids, paintShape, type DotShape } from '@/components/ds/ui/dot-story-cells';
import { storyCaption } from '@/components/ds/ui/story-caption';
import type { DotStoryText } from '@/components/ds/ui/dot-story-player';

/**
 * The "Control freshness" card's pictures, in the brand dot grid: a dial that sets how old a copy may be, the cache
 * a copy that is fresh enough is served from, and the live web a fresh capture goes out to.
 */

// The ring pattern behind the picture already keeps clear of it, so the dots need no halo of their own.
export const FRESHNESS_STORY_GRID: DotGrid = { columns: 58, rows: 38, pitch: 10, dotRadius: 3.2, ringStroke: 1, haloRadius: 0 };

const { columns: COLUMNS, rows: ROWS, pitch: PITCH } = FRESHNESS_STORY_GRID;
const x = (column: number) => column * PITCH;
// Doto sits a third of its size below the middle of the row it is set on.
const baselineOn = (row: number, size: number) => (row + 0.5) * PITCH + size / 3;
const pictureOfStates = (states: Uint8Array): StoryPicture => ({ states, cells: cellsOfStates(FRESHNESS_STORY_GRID, states) });
const blank = () => new Uint8Array(COLUMNS * ROWS);

// Every picture stands in the same place, left of the words that say what it means.
const CENTRE = 16;

const DIAL = { centre: { column: CENTRE, row: 25 }, radius: 14.4, band: 4, needle: 9.5, needleWidth: 0.75, hub: 2.2, ticks: 6, tickGap: 0.09 };
const isDial: DotShape = (column, row) => row <= DIAL.centre.row && Math.hypot(column - DIAL.centre.column, row - DIAL.centre.row) <= DIAL.radius;

/**
 * The dial with its needle `age` of the way from fresh (far left) to the oldest copy (far right). The band fills
 * behind the needle: every age up to the one it points at is accepted.
 */
export function paintDial(states: Uint8Array, age: number) {
	const angle = Math.PI * (1 - age);
	const tip = { column: DIAL.centre.column + DIAL.needle * Math.cos(angle), row: DIAL.centre.row - DIAL.needle * Math.sin(angle) };
	states.fill(DOT_ABSENT);
	return paintShape(FRESHNESS_STORY_GRID, states, isDial, (column, row) => {
		const fromCentre = Math.hypot(column - DIAL.centre.column, row - DIAL.centre.row);
		const along = 1 - Math.atan2(DIAL.centre.row - row, column - DIAL.centre.column) / Math.PI;
		if (fromCentre > DIAL.radius - 1 - DIAL.band) {
			const mark = along * DIAL.ticks;
			if (Math.abs(mark - Math.round(mark)) < DIAL.tickGap && Math.round(mark) % DIAL.ticks !== 0) return DOT_ABSENT;
			return along <= age ? DOT_FILLED : DOT_HOLLOW;
		}
		if (fromCentre <= DIAL.hub || distanceToSegment(column, row, DIAL.centre, tip) < DIAL.needleWidth) return DOT_FILLED;
		return DOT_ABSENT;
	});
}

export const DIAL_LABELS: DotStoryText[] = [
	{ text: 'fresh', x: x(CENTRE - DIAL.radius), y: baselineOn(DIAL.centre.row + 2.5, 12), size: 12, weight: 700, muted: true },
	{ text: 'older', x: x(CENTRE + DIAL.radius + 1), y: baselineOn(DIAL.centre.row + 2.5, 12), size: 12, weight: 700, muted: true, anchor: 'end' },
];

const CACHE = { top: 8, bottom: 30, halfWidth: 11.4, depth: 3.2, seams: [15.3, 22.6], read: { rows: 2 } };
const isOnDisc = (column: number, row: number, discRow: number) => ((column - CENTRE) / CACHE.halfWidth) ** 2 + ((row - discRow) / CACHE.depth) ** 2 <= 1;
// The front edge of a disc whose middle is on `discRow`, one dot deep in each column.
const isOnRim = (column: number, row: number, discRow: number) => row === Math.round(discRow + CACHE.depth * Math.sqrt(Math.max(0, 1 - ((column - CENTRE) / CACHE.halfWidth) ** 2)));
const isCache: DotShape = (column, row) => (row >= CACHE.top && row <= CACHE.bottom && Math.abs(column - CENTRE) <= CACHE.halfWidth) || isOnDisc(column, row, CACHE.top) || isOnDisc(column, row, CACHE.bottom);

/** The cache, a drum of three stacked discs, with a band of rings `read` of the way down it as a copy is read out (none at 0 or 1). */
export function paintCache(states: Uint8Array, read: number) {
	const readRow = CACHE.top + CACHE.depth + read * (CACHE.bottom - CACHE.top);
	states.fill(DOT_ABSENT);
	return paintShape(FRESHNESS_STORY_GRID, states, isCache, (column, row) => {
		if (isOnRim(column, row, CACHE.top)) return DOT_FILLED;
		if (isOnDisc(column, row, CACHE.top)) return DOT_HOLLOW;
		if (CACHE.seams.some((seam) => isOnRim(column, row, seam))) return DOT_ABSENT;
		const isBeingRead = read > 0 && read < 1 && Math.abs(row - readRow) < CACHE.read.rows;
		return !isBeingRead && isFilledAmongSolids(column, row) ? DOT_FILLED : DOT_HOLLOW;
	});
}

const GLOBE = { centre: { column: CENTRE, row: 19 }, radius: 14.4, meridians: 6, lineWidth: 0.55, parallels: [-0.5, 0, 0.5] };
const isGlobe: DotShape = (column, row) => Math.hypot(column - GLOBE.centre.column, row - GLOBE.centre.row) <= GLOBE.radius;
/** How far the globe turns before it looks the same again: one meridian's width. */
export const GLOBE_TURN = Math.PI / GLOBE.meridians;

/** The live web, a globe turned `turned` radians: its meridians travel across its face, its parallels stay put. */
export function paintGlobe(states: Uint8Array, turned: number) {
	states.fill(DOT_ABSENT);
	return paintShape(FRESHNESS_STORY_GRID, states, isGlobe, (column, row) => {
		const up = (row - GLOBE.centre.row) / GLOBE.radius;
		if (GLOBE.parallels.some((parallel) => Math.abs(row - GLOBE.centre.row - parallel * GLOBE.radius) < GLOBE.lineWidth)) return DOT_FILLED;
		const across = (column - GLOBE.centre.column) / (GLOBE.radius * Math.sqrt(1 - up * up));
		const longitude = Math.asin(Math.max(-1, Math.min(1, across))) + turned;
		const fromMeridian = Math.abs(longitude / GLOBE_TURN - Math.round(longitude / GLOBE_TURN)) * GLOBE_TURN;
		// A meridian is one dot wide wherever it is on the face, so its width in longitude grows towards the limb.
		const dotInLongitude = 1 / (GLOBE.radius * Math.sqrt(1 - up * up) * Math.sqrt(Math.max(0.02, 1 - across * across)));
		return fromMeridian < GLOBE.lineWidth * dotInLongitude ? DOT_FILLED : DOT_HOLLOW;
	});
}

/** The oldest copy the first request accepts, as a share of the dial. */
export const CACHED_AGE = 0.7;
export const DIAL_FRESH = pictureOfStates(paintDial(blank(), 0));
export const DIAL_CACHED = pictureOfStates(paintDial(blank(), CACHED_AGE));
export const CACHE_AT_REST = pictureOfStates(paintCache(blank(), 0));
export const GLOBE_AT_REST = pictureOfStates(paintGlobe(blank(), 0));

export const ONE_HOUR_MS = 3_600_000;
export const CAPTIONS = {
	acceptCached: storyCaption(FRESHNESS_STORY_GRID, 34, 'maxAgeMs', String(ONE_HOUR_MS), 'a copy up to 1h old is fine'),
	cached: storyCaption(FRESHNESS_STORY_GRID, 34, 'from the cache', '40 ms', 'captured 12 minutes ago'),
	requireFresh: storyCaption(FRESHNESS_STORY_GRID, 34, 'maxAgeMs', '0', 'always captured fresh'),
	fresh: storyCaption(FRESHNESS_STORY_GRID, 34, 'from the live page', '1.9 s', 'captured just now'),
};

/** The live capture: what the picture shows before it plays, and instead of playing with reduced motion. */
export const FRESHNESS_RESTING = { ...GLOBE_AT_REST, texts: CAPTIONS.fresh };

