'use client';

import { HERO_PATTERN_HOLE_ATTRIBUTE, type HeroPatternHole } from '@/components/ds/ui/hero-pattern-hole';
import { dotsPath } from '@/components/ds/ui/dot-svg-path';
import { cx as cn } from '@/components/ds/ui/cx';
import { type ReactNode, useEffect, useId, useRef, useState } from 'react';

const DESKTOP_PITCH = 16;
const MOBILE_PITCH = 12;
const MOBILE_BREAKPOINT = 640;
const DOT_RADIUS_RATIO = 0.31;
const CLEARANCE_RATIO = 1.25;
// Leaves a column of dots in the gap between carousel cards.
const TIGHT_CLEARANCE_RATIO = 0.25;
// Brings the dots up to a card without letting a ring touch it.
const SNUG_CLEARANCE_RATIO = 0.75;

// Solid clusters sit off-centre, loosely around the content, like the brand pattern posts.
const CLUSTER_TARGETS = [
	{ x: 0.12, y: 0.2 },
	{ x: 0.86, y: 0.3 },
	{ x: 0.1, y: 0.78 },
	{ x: 0.9, y: 0.84 },
];

interface Rect {
	left: number;
	top: number;
	right: number;
	bottom: number;
}

interface Hole extends Rect {
	kind: HeroPatternHole;
}

interface Dot {
	key: string;
	cx: number;
	cy: number;
}

interface ClusterShape {
	footprint: [number, number][];
	solid: [number, number][];
}

interface PatternLayout {
	radius: number;
	hollow: Dot[];
	solid: Dot[];
}

function diamondShape(radius: number): ClusterShape {
	const cells: [number, number][] = [];
	for (let dy = -radius; dy <= radius; dy++) {
		for (let dx = -radius; dx <= radius; dx++) {
			if (Math.abs(dx) + Math.abs(dy) <= radius) cells.push([dx, dy]);
		}
	}
	return { footprint: cells, solid: cells };
}

// Text holes follow each rendered line rather than the element's box, so the cut-out traces a headline's ragged edge.
function measureHoles(container: HTMLElement): Hole[] {
	const origin = container.getBoundingClientRect();
	const rects: Hole[] = [];
	for (const element of container.querySelectorAll<HTMLElement>(`[${HERO_PATTERN_HOLE_ATTRIBUTE}]`)) {
		const kind = element.getAttribute(HERO_PATTERN_HOLE_ATTRIBUTE) as HeroPatternHole;
		const boxes = kind === 'text' ? textLineBoxes(element) : [element.getBoundingClientRect()];
		for (const box of boxes) {
			if (box.width === 0 || box.height === 0) continue;
			rects.push({ left: box.left - origin.left, top: box.top - origin.top, right: box.right - origin.left, bottom: box.bottom - origin.top, kind });
		}
	}
	return rects;
}

function textLineBoxes(element: HTMLElement) {
	const range = document.createRange();
	range.selectNodeContents(element);
	return Array.from(range.getClientRects());
}

// Rows and columns are stretched by a fraction of a pixel so the outer dots sit exactly half a pitch inside every edge:
// no dot is cropped, and two patterned sections that touch continue at the same spacing across their seam.
function fitAxis(extent: number, pitch: number) {
	const count = Math.max(1, Math.round(extent / pitch));
	const step = count > 1 ? (extent - pitch) / (count - 1) : 0;
	return { count, position: (index: number) => pitch / 2 + index * step };
}

function isInside(hole: Rect, x: number, y: number, clearance: number) {
	return x > hole.left - clearance && x < hole.right + clearance && y > hole.top - clearance && y < hole.bottom + clearance;
}

function buildLayout(width: number, height: number, holes: Hole[], withClusters: boolean): PatternLayout {
	const isMobile = width < MOBILE_BREAKPOINT;
	const pitch = isMobile ? MOBILE_PITCH : DESKTOP_PITCH;
	const clearanceFor = (hole: Hole) => pitch * (hole.kind === 'tight-box' ? TIGHT_CLEARANCE_RATIO : hole.kind === 'snug-box' ? SNUG_CLEARANCE_RATIO : CLEARANCE_RATIO);
	const { count: columns, position: columnX } = fitAxis(width, pitch);
	const { count: rows, position: rowY } = fitAxis(height, pitch);
	const clearingHoles = holes.filter((hole) => hole.kind !== 'cover');
	const covers = holes.filter((hole) => hole.kind === 'cover');

	const visible = new Uint8Array(columns * rows);
	const covered = new Uint8Array(columns * rows);
	for (let row = 0; row < rows; row++) {
		for (let column = 0; column < columns; column++) {
			const index = row * columns + column;
			visible[index] = clearingHoles.some((hole) => isInside(hole, columnX(column), rowY(row), clearanceFor(hole))) ? 0 : 1;
			covered[index] = covers.some((cover) => isInside(cover, columnX(column), rowY(row), pitch * TIGHT_CLEARANCE_RATIO)) ? 1 : 0;
		}
	}
	const inGrid = (column: number, row: number) => column >= 0 && row >= 0 && column < columns && row < rows;
	const isVisible = (column: number, row: number) => inGrid(column, row) && visible[row * columns + column] === 1;

	const diamond = diamondShape(isMobile ? 2 : 3);
	const solidCells = new Set<string>();
	const claimedCells = new Set<string>();
	const isFree = (column: number, row: number) => isVisible(column, row) && covered[row * columns + column] === 0 && !claimedCells.has(`${column}:${row}`);
	for (const target of withClusters ? CLUSTER_TARGETS : []) {
		const anchor = nearestClusterAnchor(target.x * (columns - 1), target.y * (rows - 1), diamond.footprint, isFree, columns, rows);
		if (!anchor) continue;
		for (const [dx, dy] of diamond.footprint) claimedCells.add(`${anchor.column + dx}:${anchor.row + dy}`);
		for (const [dx, dy] of diamond.solid) solidCells.add(`${anchor.column + dx}:${anchor.row + dy}`);
	}

	const hollow: Dot[] = [];
	const solid: Dot[] = [];
	for (let row = 0; row < rows; row++) {
		for (let column = 0; column < columns; column++) {
			if (!isVisible(column, row)) continue;
			const key = `${column}:${row}`;
			const dot = { key, cx: columnX(column), cy: rowY(row) };
			(solidCells.has(key) ? solid : hollow).push(dot);
		}
	}
	return { radius: pitch * DOT_RADIUS_RATIO, hollow, solid };
}

function nearestClusterAnchor(targetColumn: number, targetRow: number, cluster: [number, number][], isVisible: (column: number, row: number) => boolean, columns: number, rows: number) {
	let best: { column: number; row: number; distance: number } | null = null;
	for (let row = 0; row < rows; row++) {
		for (let column = 0; column < columns; column++) {
			const distance = (column - targetColumn) ** 2 + (row - targetRow) ** 2;
			if (best && distance >= best.distance) continue;
			if (cluster.every(([dx, dy]) => isVisible(column + dx, row + dy))) best = { column, row, distance };
		}
	}
	return best;
}

// Only the plain ring tone lights up under the pointer; the other tones sit behind animated demos, where a moving
// spotlight would be one motion too many.
const PATTERN_TONES = {
	onBlue: { color: 'var(--ds-color-white)', hollowOpacity: 1, solidOpacity: 1, hoverOpacity: 0 },
	subtle: { color: 'var(--ds-color-brand)', hollowOpacity: 0.14, solidOpacity: 0.3, hoverOpacity: 0 },
	rings: { color: 'var(--ds-color-brand)', hollowOpacity: 0.25, solidOpacity: 0.4, hoverOpacity: 0.5 },
} as const;

const SPOTLIGHT_RADIUS_IN_DOTS = 6;

// Fills the rings nearest the pointer through a soft radial mask. Only the mask's circle moves, so following the
// pointer costs two attribute writes a frame rather than repainting dots one by one.
function useSpotlight(container: HTMLDivElement | null, enabled: boolean) {
	const spotlightRef = useRef<SVGCircleElement>(null);
	const [lit, setLit] = useState(false);

	useEffect(() => {
		const spotlight = spotlightRef.current;
		if (!container || !spotlight || !enabled || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
		let frame = 0;
		let point = { x: 0, y: 0 };
		const place = () => {
			frame = 0;
			spotlight.setAttribute('cx', String(point.x));
			spotlight.setAttribute('cy', String(point.y));
		};
		const onPointerMove = (event: PointerEvent) => {
			if (event.pointerType !== 'mouse') return;
			const origin = container.getBoundingClientRect();
			point = { x: event.clientX - origin.left, y: event.clientY - origin.top };
			if (!frame) frame = requestAnimationFrame(place);
			setLit(true);
		};
		const onPointerLeave = () => setLit(false);
		container.addEventListener('pointermove', onPointerMove, { passive: true });
		container.addEventListener('pointerleave', onPointerLeave);
		return () => {
			cancelAnimationFrame(frame);
			container.removeEventListener('pointermove', onPointerMove);
			container.removeEventListener('pointerleave', onPointerLeave);
		};
	}, [container, enabled]);

	return { spotlightRef, lit };
}

/**
 * Brand dot grid that clears itself around every descendant marked with the hole attribute, so the empty space takes
 * the content's shape. Its solid clusters are the brand's diamonds; `clusters={false}` leaves only the plain rings.
 */
export function HeroCirclePatternSurface({ className, tone = 'onBlue', clusters = true, children }: { className?: string; tone?: keyof typeof PATTERN_TONES; clusters?: boolean; children: ReactNode }) {
	const toneStyle = PATTERN_TONES[tone];
	const [container, setContainer] = useState<HTMLDivElement | null>(null);
	const [layout, setLayout] = useState<PatternLayout | null>(null);
	const hasSpotlight = toneStyle.hoverOpacity > 0;
	const { spotlightRef, lit } = useSpotlight(container, hasSpotlight && layout !== null);
	const maskId = `pattern-spotlight-${useId().replace(/:/g, '')}`;

	useEffect(() => {
		if (!container) return;

		let frame = 0;
		const relayout = () => {
			cancelAnimationFrame(frame);
			frame = requestAnimationFrame(() => setLayout(buildLayout(container.clientWidth, container.clientHeight, measureHoles(container), clusters)));
		};

		const observer = new ResizeObserver(relayout);
		observer.observe(container);
		for (const hole of container.querySelectorAll(`[${HERO_PATTERN_HOLE_ATTRIBUTE}]`)) {
			observer.observe(hole);
			if (hole.parentElement) observer.observe(hole.parentElement);
		}
		void document.fonts.ready.then(relayout);

		return () => {
			cancelAnimationFrame(frame);
			observer.disconnect();
		};
	}, [clusters, container]);

	return (
		<div ref={setContainer} className={cn('relative', className)}>
			<svg aria-hidden="true" className={cn('pointer-events-none absolute inset-0 size-full transition-opacity duration-700 motion-reduce:transition-none', layout ? 'opacity-100' : 'opacity-0')}>
				{layout && (
					<>
						<path fill="none" style={{ stroke: toneStyle.color }} strokeWidth="1" opacity={toneStyle.hollowOpacity} d={dotsPath(layout.hollow, layout.radius - 0.5)} />
						<path style={{ fill: toneStyle.color }} opacity={toneStyle.solidOpacity} d={dotsPath(layout.solid, layout.radius)} />
						{hasSpotlight && (
							<>
								<defs>
									<radialGradient id={`${maskId}-falloff`}>
										<stop offset="0%" stopColor="white" />
										<stop offset="100%" stopColor="black" />
									</radialGradient>
									<mask id={maskId}>
										<circle ref={spotlightRef} cx={-9999} cy={-9999} r={(layout.radius / DOT_RADIUS_RATIO) * SPOTLIGHT_RADIUS_IN_DOTS} fill={`url(#${maskId}-falloff)`} />
									</mask>
								</defs>
								<path mask={`url(#${maskId})`} className="transition-opacity duration-500 ease-out motion-reduce:transition-none" style={{ fill: toneStyle.color, opacity: lit ? toneStyle.hoverOpacity : 0 }} d={dotsPath([...layout.hollow, ...layout.solid], layout.radius - 0.5)} />
							</>
						)}
					</>
				)}
			</svg>
			{children}
		</div>
	);
}

import { CAPTIONS, CHART_ARRIVES_DRAWN, CHART_DRAWN, CHART_STARTED, DOMAIN_GLOBE, ENVELOPE_PICTURE, IDENTITY_STORY_GRID, NAME_BADGE, SEAL_TICKED, SEAL_UNTICKED, paintChart, paintSeal } from '@/components/ds/ui/identity-story-scenes';
import { captionedBeat } from '@/components/ds/ui/story-caption';
import { createBeatStoryPlayer } from '@/components/ds/ui/dot-story-beats';
import { clamp01, easeOut } from '@/components/ds/ui/dot-story-cells';
import type { DotStoryPlayer, DotStoryStage } from '@/components/ds/ui/dot-story-player';

/**
 * One lookup, played as a loop: the four identifiers a brand can be found by melt into one another, a domain's
 * globe, an email's envelope, a name badge and a ticker's chart drawing its line; then the chart melts into a seal,
 * and its tick is cut as the brand they all resolve to is named.
 */

const IDENTIFIER_HOLD_SECONDS = 1.7;
const DRAWING = { startsAt: 0.2, seconds: 1 };
const TICKING = { startsAt: 0.3, seconds: 0.5 };

export function createIdentityStoryPlayer(stage: DotStoryStage): DotStoryPlayer {
	return createBeatStoryPlayer(stage, {
		grid: IDENTITY_STORY_GRID,
		resting: { beat: 4, heldSeconds: 2 },
		beats: [
			captionedBeat({ picture: DOMAIN_GLOBE, caption: CAPTIONS.domain, holdSeconds: IDENTIFIER_HOLD_SECONDS, isTyped: true }),
			captionedBeat({ picture: ENVELOPE_PICTURE, caption: CAPTIONS.email, holdSeconds: IDENTIFIER_HOLD_SECONDS, isTyped: true }),
			captionedBeat({ picture: NAME_BADGE, caption: CAPTIONS.name, holdSeconds: IDENTIFIER_HOLD_SECONDS, isTyped: true }),
			captionedBeat({
				picture: CHART_STARTED,
				departure: CHART_DRAWN,
				caption: CAPTIONS.ticker,
				holdSeconds: IDENTIFIER_HOLD_SECONDS + 0.3,
				isTyped: true,
				animate: (states, heldSeconds) => void paintChart(states, CHART_ARRIVES_DRAWN + (1 - CHART_ARRIVES_DRAWN) * easeOut(clamp01((heldSeconds - DRAWING.startsAt) / DRAWING.seconds))),
			}),
			captionedBeat({
				picture: SEAL_UNTICKED,
				departure: SEAL_TICKED,
				caption: CAPTIONS.brand,
				holdSeconds: 3.4,
				animate: (states, heldSeconds) => void paintSeal(states, clamp01((heldSeconds - TICKING.startsAt) / TICKING.seconds)),
			}),
		],
	});
}

import { GLOBE_AT_REST } from '@/components/ds/ui/freshness-story-scenes';
import { storyCaption } from '@/components/ds/ui/story-caption';
import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from '@/components/ds/ui/dot-morph-dots';
import type { StoryPicture } from '@/components/ds/ui/dot-story-beats';
import { cellsOfStates, distanceToSegment, paintShape, solidWithSpeckle, type DotShape, type GridPoint } from '@/components/ds/ui/dot-story-cells';

/**
 * The "Resolve an identity" card's pictures, in the brand dot grid: the four things a brand can be looked up by, a
 * domain's globe, an email's envelope, a name badge and a ticker's chart, and the seal that says which brand it is.
 */

// The ring pattern behind the picture already keeps clear of it, so the dots need no halo of their own.
export const IDENTITY_STORY_GRID: DotGrid = { columns: 58, rows: 38, pitch: 10, dotRadius: 3.2, ringStroke: 1, haloRadius: 0 };

const { columns: COLUMNS, rows: ROWS } = IDENTITY_STORY_GRID;
const pictureOfStates = (states: Uint8Array): StoryPicture => ({ states, cells: cellsOfStates(IDENTITY_STORY_GRID, states) });
const blank = () => new Uint8Array(COLUMNS * ROWS);
const between = (value: number, from: number, to: number) => value >= from && value <= to;

// Every picture stands in the same place, left of the words that say what it is.
const CENTRE = 16;
const LINE_WIDTH = 0.6;

export const DOMAIN_GLOBE = GLOBE_AT_REST;

const ENVELOPE = { left: 3, right: 29, top: 8, bottom: 29, flapTo: { column: CENTRE, row: 20 } };
const isEnvelope: DotShape = (column, row) => between(column, ENVELOPE.left, ENVELOPE.right) && between(row, ENVELOPE.top, ENVELOPE.bottom);
// How far down the flap's edge is in this column: it runs from each top corner to a point in the middle.
const flapEdge = (column: number) => ENVELOPE.top + ((ENVELOPE.flapTo.row - ENVELOPE.top) * Math.min(column - ENVELOPE.left, ENVELOPE.right - column)) / (CENTRE - ENVELOPE.left);

export const ENVELOPE_PICTURE = pictureOfStates(
	paintShape(IDENTITY_STORY_GRID, blank(), isEnvelope, (column, row) => {
		const belowFlap = row - flapEdge(column);
		if (Math.abs(belowFlap) < 0.8) return DOT_FILLED;
		return belowFlap < 0 ? solidWithSpeckle(column, row) : DOT_HOLLOW;
	})
);

const BADGE = { left: 4, right: 28, top: 7, bottom: 31, clip: { left: 13, right: 19, top: 3 }, header: 13, name: { top: 18, bottom: 21, left: 8, right: 24 }, line: { row: 25, left: 10, right: 22 } };
const isBadge: DotShape = (column, row) => (between(column, BADGE.left, BADGE.right) && between(row, BADGE.top, BADGE.bottom)) || (between(column, BADGE.clip.left, BADGE.clip.right) && between(row, BADGE.clip.top, BADGE.top));

// A name badge on its clip: a solid band across the top, the name in solid dots, a quieter line under it.
export const NAME_BADGE = pictureOfStates(
	paintShape(IDENTITY_STORY_GRID, blank(), isBadge, (column, row) => {
		if (row <= BADGE.header) return DOT_FILLED;
		if (between(row, BADGE.name.top, BADGE.name.bottom) && between(column, BADGE.name.left, BADGE.name.right)) return DOT_FILLED;
		if (row === BADGE.line.row && between(column, BADGE.line.left, BADGE.line.right)) return DOT_ABSENT;
		return DOT_HOLLOW;
	})
);

const CHART = { left: 4, right: 29, top: 5, bottom: 31, lineWidth: 1 };
const PRICES: GridPoint[] = [
	{ column: 5, row: 27 },
	{ column: 10, row: 21 },
	{ column: 14, row: 24 },
	{ column: 20, row: 14 },
	{ column: 24, row: 17 },
	{ column: 29, row: 7 },
];
const fromPriceLine = (column: number, row: number) => Math.min(...PRICES.slice(1).map((point, index) => distanceToSegment(column, row, PRICES[index], point)));
const priceAt = (column: number) => {
	const to = Math.max(1, PRICES.findIndex((point) => point.column >= column));
	const from = PRICES[to - 1];
	return from.row + ((PRICES[to].row - from.row) * (column - from.column)) / (PRICES[to].column - from.column);
};

/** A ticker's chart with `drawn` of its price line in, from the left: two axes, the line, and rings filling under it. */
export function paintChart(states: Uint8Array, drawn: number) {
	const drawnTo = CHART.left + drawn * (CHART.right - CHART.left);
	for (let row = 0; row < ROWS; row++) {
		for (let column = 0; column < COLUMNS / 2 + 2; column++) {
			const cell = row * COLUMNS + column;
			const isAxis = (column === CHART.left && between(row, CHART.top, CHART.bottom)) || (row === CHART.bottom && between(column, CHART.left, CHART.right));
			if (isAxis) states[cell] = DOT_FILLED;
			else if (column <= CHART.left || column > Math.min(drawnTo, CHART.right) || row >= CHART.bottom) states[cell] = DOT_ABSENT;
			else if (fromPriceLine(column, row) < CHART.lineWidth) states[cell] = DOT_FILLED;
			else states[cell] = row > priceAt(column) ? DOT_HOLLOW : DOT_ABSENT;
		}
	}
	return states;
}

/** How much of the price line is already in when the chart arrives; an axis alone has too little in it to melt into. */
export const CHART_ARRIVES_DRAWN = 0.35;
export const CHART_STARTED = pictureOfStates(paintChart(blank(), CHART_ARRIVES_DRAWN));
export const CHART_DRAWN = pictureOfStates(paintChart(blank(), 1));

const SEAL = { centre: { column: CENTRE, row: 19 }, radius: 12, scallop: 1.4, scallops: 8, tick: { from: { column: 10, row: 19.5 }, corner: { column: 14.5, row: 24 }, to: { column: 22.5, row: 14 }, width: 1.3 } };
const isSeal: DotShape = (column, row) => {
	const across = column - SEAL.centre.column;
	const down = row - SEAL.centre.row;
	return Math.hypot(across, down) <= SEAL.radius + SEAL.scallop * Math.cos(SEAL.scallops * Math.atan2(down, across));
};
const isTick = (column: number, row: number) => Math.min(distanceToSegment(column, row, SEAL.tick.from, SEAL.tick.corner), distanceToSegment(column, row, SEAL.tick.corner, SEAL.tick.to)) < SEAL.tick.width;

/** The seal, with `ticked` of its tick cut out of it in rings, from the tick's short stroke to the end of its long one. */
export function paintSeal(states: Uint8Array, ticked: number) {
	const tickedTo = SEAL.tick.from.column - 2 + ticked * (SEAL.tick.to.column + 4 - SEAL.tick.from.column);
	return paintShape(IDENTITY_STORY_GRID, states, isSeal, (column, row) => {
		if (isTick(column, row) && column <= tickedTo) return DOT_HOLLOW;
		return DOT_FILLED;
	});
}

export const SEAL_UNTICKED = pictureOfStates(paintSeal(blank(), 0));
export const SEAL_TICKED = pictureOfStates(paintSeal(blank(), 1));

const caption = (label: string, value: string, detail: string) => storyCaption(IDENTITY_STORY_GRID, 34, label, value, detail);
export const CAPTIONS = {
	domain: caption('look up by', 'domain', 'shopify.com'),
	email: caption('or by', 'email', 'ana@shopify.com'),
	name: caption('or by', 'name', '"Shopify"'),
	ticker: caption('or by', 'ticker', 'SHOP'),
	brand: caption('all four resolve to', 'Shopify', 'one brand profile'),
};

/** The resolved brand: what the picture shows before it plays, and instead of playing with reduced motion. */
export const IDENTITY_RESTING = { ...SEAL_TICKED, texts: CAPTIONS.brand };

